===== AssignMembershipLevel =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.function.common.Membership;

/**
 * Step of {@code POST /api/owners} that stamps the owner's numeric {@code membershipLevel},
 * applying the household ceiling: a new owner's level cannot exceed one above the current maximum
 * membershipLevel among their existing household members. With no existing household member no cap
 * applies and the owner keeps the level its own points earn.
 *
 * <p>The ceiling is evaluated over the household as it currently stands: each existing member sharing
 * this owner's {@code householdId} is re-scored with the current household size (this owner's
 * {@code householdMemberCount}, set by {@link AssignHouseholdSize}), so a member created when the
 * household was smaller still counts toward the ceiling at its current standing. The capped value is
 * stored on the owner and returned by the response mapper; {@code membershipPoints} is unaffected.
 *
 * <p>Runs after {@link AssignHouseholdSize} (which stamps {@code householdId} upstream via
 * {@link AssignHousehold} and this owner's {@code householdMemberCount}) and before {@link SaveOwner},
 * so the count reflects the existing members plus this owner and the level persists.
 */
public class AssignMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int naturalLevel = Membership.levelOf(owner);
        String householdId = owner.getHouseholdId();
        Integer householdSize = owner.getHouseholdMemberCount();

        int maxExistingLevel = 0;
        boolean hasExistingMember = false;
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    hasExistingMember = true;
                    maxExistingLevel = Math.max(maxExistingLevel,
                            Membership.levelOf(existing, householdSize));
                }
            }
        }

        // With no existing household member no cap applies.
        int level = hasExistingMember ? Math.min(naturalLevel, maxExistingLevel + 1) : naturalLevel;
        owner.setMembershipLevel(level);
    }
}
===== AssignCustomerCode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.function.common.CustomerCodes;

/**
 * Step of {@code POST /api/owners} that assigns the owner's {@code customerCode}, formatted
 * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the postcode (falling
 * back to the city, see {@link org.springframework.samples.petclinic.rest.function.common.Localities})
 * and {@code HASH8} is the first eight upper-case hex characters of
 * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
 *
 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}; {@code @Val} yields the built owner so
 * the code is mutated in place and persisted by the save step. The identity is derived entirely from
 * the owner's own fields — the telephone is already normalized to E.164 by this point — so it is
 * seed-independent.
 *
 * <p>Should the computed code collide with an existing owner's {@code customerCode}, {@code '-<n>'} is
 * appended with the smallest {@code n >= 2} that makes it unique, so distinct owners always receive
 * distinct codes.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getCustomerCode() != null) {
                taken.add(existing.getCustomerCode());
            }
        }
        owner.setCustomerCode(CustomerCodes.deduplicate(CustomerCodes.of(owner), taken));
    }
}
===== OwnerCreatedEvent =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Immutable structured audit event emitted on a successful owner create, alongside the human-readable
 * audit line. Serialised to a compact JSON object
 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} and published to the
 * dedicated {@code AUDIT} logger by {@link AuditOwnerCreated}.
 *
 * <p>The {@code seq} is a monotonically increasing sequence across creates. The {@code identifier} is
 * the owner's <em>current primary identifier</em>: today the {@code customerCode}, and whatever
 * replaces it later — when the {@code customerCode} is unified into the {@code memberId}, this event
 * carries the {@code memberId} instead. It is serialised under the {@code customerCode} key.
 *
 * <p>The record is deliberately immutable: once constructed its fields never change, so an event that
 * has been emitted cannot be retroactively altered.
 */
public record OwnerCreatedEvent(long seq, int ownerId, String identifier, int membershipLevel) {

    /** The event marker. */
    public static final String EVENT = "OWNER_CREATED";

    /** This event as a compact JSON object string. */
    public String toJson() {
        return "{"
                + "\"seq\":" + this.seq
                + ",\"ownerId\":" + this.ownerId
                + ",\"customerCode\":" + quote(this.identifier)
                + ",\"membershipLevel\":" + this.membershipLevel
                + ",\"event\":\"" + EVENT + "\""
                + "}";
    }

    private static String quote(String value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }
}
===== AuditOwnerCreated =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.function.common.Membership;

/**
 * Step of {@code POST /api/owners} that emits an audit record for a successful create. Runs after
 * {@link SaveOwner} (so the owner's generated id is available) and before
 * {@link RespondWithOwnerCreated}.
 *
 * <p>Publishes two things to the dedicated {@code AUDIT} logger:
 * <ul>
 * <li>the human-readable audit line carrying the owner id, the assigned {@code customerCode}, the
 * stored (business-day-adjusted) {@code registrationDate}, the numeric {@code membershipLevel} and the
 * assigned {@code membershipNumber}; and
 * <li>an immutable structured {@link OwnerCreatedEvent} as a JSON object
 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}, where {@code seq} is a
 * monotonically increasing integer across creates and the identifier is the owner's current primary
 * identifier (the {@code customerCode} today; the {@code memberId} once the two are unified).
 * </ul>
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /** Monotonically increasing sequence across creates, process-wide. */
    private static final AtomicLong SEQUENCE = new AtomicLong(0);

    public void service(@Val Owner owner) {
        int membershipLevel = owner.getMembershipLevel() != null ? owner.getMembershipLevel()
                : Membership.levelOf(owner);

        AUDIT.info(
                "Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), membershipLevel,
                owner.getMembershipNumber());

        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
                primaryIdentifierOf(owner), membershipLevel);
        AUDIT.info(event.toJson());
    }

    /**
     * The owner's current primary identifier carried by the structured event. Today this is the
     * {@code customerCode}; when the {@code customerCode} is unified into the {@code memberId}, this
     * single accessor becomes the place that yields the {@code memberId} instead.
     */
    private static String primaryIdentifierOf(Owner owner) {
        return owner.getCustomerCode();
    }
}
===== Localities =====
package org.springframework.samples.petclinic.rest.function.common;

import java.util.Map;

/**
 * Region lookup for the owner's derived 'locality'. The postcode is preferred: it is resolved
 * against the pinned ranges first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, see
 * {@link Postcodes}), and only when the postcode is absent or in no known range does the
 * lookup fall back to the pinned city-to-region table (Sydney -> NSW, Melbourne -> VIC,
 * Brisbane -> QLD). Any other (or missing) city derives the canonical region "UNKNOWN".
 */
public final class Localities {

    private static final String UNKNOWN = "UNKNOWN";

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW",
            "Melbourne", "VIC",
            "Brisbane", "QLD");

    private Localities() {
    }

    /**
     * The canonical region for the owner, preferring the postcode. Resolves {@code postcode}
     * against the pinned ranges first and only falls back to {@code city} when the postcode is
     * absent or in no known range. This returns the same region for a known city but
     * disambiguates cities that share a name.
     */
    public static String of(String postcode, String city) {
        String byPostcode = Postcodes.regionOf(postcode);
        return byPostcode != null ? byPostcode : of(city);
    }

    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
    public static String of(String city) {
        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
    }
}
===== Membership =====
package org.springframework.samples.petclinic.rest.function.common;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the owner's {@code membershipPoints} and the numeric {@code membershipLevel} mapped from
 * them.
 *
 * <p>Points start at 0 and accumulate: 2 when the owner has an email address on record, 1 when the
 * owner had no namesakes at creation ({@code namesakeCount} is 0), 2 for a household of 3 or more
 * members, and 3 when the owner's tenure exceeds one elapsed fiscal year. The points then map to a
 * level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly created owner
 * has zero tenure, the +3 tenure award is out of reach at creation, so a new owner scores at most 5
 * points (2 email + 1 namesake + 2 household) and never exceeds level 3.
 */
public final class Membership {

    /** Household size, in members, at or above which the household points are granted. */
    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;

    /** Tenure, in elapsed fiscal years, that must be exceeded before the tenure points are granted. */
    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;

    private Membership() {
    }

    /** The owner's membership points, from 0 upwards. */
    public static int pointsOf(Owner owner) {
        return pointsOf(owner, owner.getHouseholdMemberCount());
    }

    /**
     * The owner's membership points as if its household had {@code householdMemberCount} members —
     * every factor except the household award is read from the owner as stored; the household award
     * (+2 for {@value #HOUSEHOLD_SIZE_FOR_POINTS} or more members) is granted from the supplied count.
     * Used to score existing household members in the household as it currently stands rather than as
     * it stood when each was created.
     */
    public static int pointsOf(Owner owner, Integer householdMemberCount) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += 1;
        }
        if (householdMemberCount != null && householdMemberCount >= HOUSEHOLD_SIZE_FOR_POINTS) {
            points += 2;
        }
        if (FiscalYears.elapsedSinceRegistration(owner) > TENURE_FISCAL_YEARS_FOR_POINTS) {
            points += 3;
        }
        return points;
    }

    /** The owner's numeric membership level, mapped from {@link #pointsOf(Owner)}: 1 for 0-1
     * points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
    public static int levelOf(Owner owner) {
        return levelForPoints(pointsOf(owner));
    }

    /** The numeric membership level the owner would hold in a household of the given size (see
     * {@link #pointsOf(Owner, Integer)}). */
    public static int levelOf(Owner owner, Integer householdMemberCount) {
        return levelForPoints(pointsOf(owner, householdMemberCount));
    }

    /** Map membership points to a level: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
    public static int levelForPoints(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }
}

