package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import tools.jackson.databind.node.ObjectNode;

/**
 * ownerSegment: '<TIER>_<AREA>'. TIER is 'PREMIUM' when membershipLevel is 3 or more, otherwise
 * 'STANDARD'. AREA is 'METRO' when the locality is a known region (NSW, VIC or QLD), otherwise
 * 'REGIONAL'.
 */
@Tag("owner-segment")
class OwnerSegmentTests extends AcceptanceBase {

	/** Lone owner, unknown city, no email: level 1 (STANDARD), UNKNOWN region (REGIONAL). */
	@Test
	void standardRegional() throws Exception {
		int id = createOwnerOk(ownerNode());
		getOwner(id).andExpect(jsonPath("$.membershipLevel").value(1))
				.andExpect(jsonPath("$.locality").value("UNKNOWN"))
				.andExpect(jsonPath("$.ownerSegment").value("STANDARD_REGIONAL"));
	}

	/** Lone owner in a NSW postcode: level 1 (STANDARD), NSW region (METRO). */
	@Test
	void standardMetro() throws Exception {
		int id = createOwnerOk(withPostcode(ownerNode()));
		getOwner(id).andExpect(jsonPath("$.membershipLevel").value(1))
				.andExpect(jsonPath("$.locality").value("NSW"))
				.andExpect(jsonPath("$.ownerSegment").value("STANDARD_METRO"));
	}

	/** Third household member (NSW) with an email: level 3 (PREMIUM), NSW region (METRO). */
	@Test
	void premiumMetro() throws Exception {
		int id = createHouseholdOfThree("2000");
		getOwner(id).andExpect(jsonPath("$.membershipLevel").value(3))
				.andExpect(jsonPath("$.locality").value("NSW"))
				.andExpect(jsonPath("$.ownerSegment").value("PREMIUM_METRO"));
	}

	/** Third household member in a postcode outside every known range: level 3 (PREMIUM), UNKNOWN
	 *  region (REGIONAL). */
	@Test
	void premiumRegional() throws Exception {
		int id = createHouseholdOfThree("5000");
		getOwner(id).andExpect(jsonPath("$.membershipLevel").value(3))
				.andExpect(jsonPath("$.locality").value("UNKNOWN"))
				.andExpect(jsonPath("$.ownerSegment").value("PREMIUM_REGIONAL"));
	}

	/** Create three owners sharing a household (same lastName + postcode); the third has an email so
	 *  it scores 5 points (2 email + 1 namesake + 2 household) → level 3. Returns the third's id. */
	private int createHouseholdOfThree(String postcode) throws Exception {
		String lastName = uniqueLastName();
		int last = 0;
		for (int i = 0; i < 3; i++) {
			ObjectNode m = ownerNode();
			m.put("postcode", postcode);
			m.put("lastName", lastName);
			m.put("firstName", uniqueFirstName());
			m.put("sharesHousehold", true);
			if (i == 2) {
				m.put("email", uniqueEmail());
			}
			last = createOwnerOk(m);
		}
		return last;
	}
}

